'use strict';
// Private, account-scoped device records. Never included in public profiles or cloud payloads.
const careerVersion='20261023-1';
const careerPrintCSS=`@page{size:A4 portrait;margin:14mm 12mm}.career-cv{box-sizing:border-box;width:186mm;max-width:none;margin:0 auto;padding:0;background:white;color:#111;font:10pt Arial,sans-serif;line-height:1.3}.career-cv *{box-sizing:border-box;color:#111}.cv-header{display:flex;align-items:center;justify-content:space-between;min-height:47mm;margin-bottom:5mm}.cv-header h1{font-size:24pt;line-height:1.1;margin:0 8mm 3mm 0;overflow-wrap:anywhere}.cv-header p{margin:0}.cv-portrait,.cv-photo-placeholder{width:35mm;height:45mm;object-fit:cover;flex:none;border:1px solid #aaa}.cv-photo-placeholder{display:grid;place-items:center;color:#777;font-size:9pt}.cv-section{margin:0 0 3mm}.cv-section h2{background:#2f7048;color:#fff;font-size:10pt;padding:2mm;margin:0;break-after:avoid;print-color-adjust:exact;-webkit-print-color-adjust:exact}.cv-table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9pt}.cv-table th,.cv-table td{border:1px solid #333;padding:1.5mm;vertical-align:top;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;min-height:5mm}.cv-table thead{display:table-header-group}.cv-table th{font-weight:bold;background:#edf1ee;print-color-adjust:exact;-webkit-print-color-adjust:exact}.cv-table tr{break-inside:avoid}.cv-personal th{width:18%;background:white;font-size:8pt;text-transform:uppercase}.cv-personal td{width:32%}.cv-sea{font-size:8pt}.cv-sea th,.cv-sea td{padding:1mm}.cv-sea th:nth-child(5){width:14%}.cv-objective{white-space:pre-wrap;overflow-wrap:anywhere;min-height:12mm;border:1px solid #333;padding:2mm;margin:0}.cv-declaration{font-size:9pt;margin:6mm 0;break-inside:avoid}.cv-signature{margin-left:auto;width:70mm;text-align:center;break-inside:avoid}.cv-signature img{display:block;width:55mm;height:15mm;object-fit:contain;margin:0 auto}.cv-signature-space{height:15mm}.cv-signature strong{display:block;border-bottom:1px solid #333;padding:1mm;overflow-wrap:anywhere}.cv-signature span{font-size:9pt}@media print{.career-cv{width:100%;margin:0}.cv-section h2{break-after:avoid}.career-cv a{color:#111;text-decoration:none}}`;
let careerOwner='',careerData=null,careerLoading=false,careerError='',careerView='home',careerSection='',careerEditId=null,careerDraft=null,careerDirty=false,careerBusy=false,careerEpoch=0,careerDBPromise=null,careerURLs=[];
const careerPersonal=[['fullName','Full name'],['familyName','Family name'],['firstName','First name'],['middleName','Middle name'],['birthDate','Birthdate','date'],['gender','Gender'],['civilStatus','Civil status'],['nationality','Nationality'],['religion','Religion'],['address','Complete address'],['contact','Contact number'],['email','Email address','email'],['height','Height'],['weight','Weight'],['availability','Availability'],['philhealth','PhilHealth number'],['pagibig','Pag-IBIG number'],['sss','SSS number'],['tin','TIN'],['objective','Objectives','textarea']];
const careerSchemas={
 education:{title:'Education',singular:'Education record',fields:[['level','Level','select',['Tertiary school','Senior high school','Secondary school','Primary school','Other']],['school','Name of school'],['years','School years'],['course','Course']]},
 certificates:{title:'Certificates',singular:'Certificate',fields:[['title','Certificate name'],['number','Certificate number'],['issuer','Issuing authority'],['issued','Date issued','date'],['expires','Expiry date','date'],['validity','Validity','select',['Has expiry date','No expiry stated','Revalidation not required']],['notes','Notes','textarea']]},
 documents:{title:'IDs & travel documents',singular:'ID or document',fields:[['category','Category','select',['Travel document','Government ID','Other']],['title','Document / ID type'],['number','Document / ID number'],['issuer','Issuing authority'],['issued','Issue date','date'],['expires','Expiry date','date'],['validity','Validity','select',['Has expiry date','No expiry stated','Revalidation not required']],['notes','Notes','textarea']]},
 vaccinations:{title:'Vaccination records',singular:'Vaccination record',fields:[['title','Vaccine'],['number','Record number'],['issued','Date issued','date'],['expires','Expiry date','date'],['validity','Validity','select',['Has expiry date','Lifetime stated on record','No expiry stated']],['notes','Notes','textarea']]},
 employment:{title:'Employment',singular:'Employment record',fields:[['company','Company'],['position','Position'],['location','Location'],['joined','Date hired','date'],['signedOff','Date resigned','date'],['current','Currently employed','checkbox']]},
 sea:{title:'Sea service',singular:'Sea service record',fields:[['rank','Rank'],['joined','Joined','date'],['signedOff','Signed off','date'],['current','Currently onboard','checkbox'],['vessel','Name of vessel'],['vesselType','Type of vessel'],['company','Company / manning agency'],['tonnage','Tonnage'],['tonnageUnit','Tonnage unit','select',['GT','GRT']],['kw','Engine power (kW)'],['period','Period as stated on your record (optional)'],['reason','Reason for leaving']]},
 references:{title:'Character references',singular:'Reference',fields:[['name','Name'],['position','Position'],['contact','Contact number']]},
 plans:{title:'Plans & appointments',singular:'Plan or appointment',fields:[['title','Title'],['type','Type','select',['Document renewal','Training','Application deadline','Appointment','Other']],['due','Date','date'],['time','Time','time'],['location','Location'],['reference','Appointment reference'],['notes','Notes','textarea'],['done','Completed','checkbox']]}
};
const careerCollections=Object.keys(careerSchemas);
const careerDefaultExport={government:false,documents:false,vaccinations:false,signature:false,declaration:true,photo:true};
function careerAccount(){return cloudEnabled?(cloudUser?.id||'signed-out'):'local'}
function careerReady(){return state.hubOnboardingCompleted&&(!cloudEnabled||cloudUser&&cloudReady&&!cloudRecovery&&!cloudReviewRecovery)}
function careerEmpty(){return {version:1,revision:0,personal:{},education:[],certificates:[],documents:[],vaccinations:[],employment:[],sea:[],references:[],plans:[],files:[],portrait:'',signature:'',exportOptions:{...careerDefaultExport}}}
function careerText(v,max=5000){return typeof v==='string'?v.slice(0,max):''}
function careerClean(raw){if(!raw||raw.version!==1)throw Error('This is not a supported Toolbox career record.');const d=careerEmpty();d.revision=Number.isSafeInteger(raw.revision)&&raw.revision>=0?raw.revision:0;for(const[k]of careerPersonal)d.personal[k]=careerText(raw.personal?.[k]);for(const type of careerCollections){if(!Array.isArray(raw[type])||raw[type].length>500)throw Error('Invalid '+type+' records.');const seen=new Set();d[type]=raw[type].map(row=>{if(!row||typeof row.id!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(row.id)||seen.has(row.id))throw Error('Invalid or duplicate record ID.');seen.add(row.id);const out={id:row.id,archived:!!row.archived};for(const[k,,kind]of careerSchemas[type].fields)out[k]=kind==='checkbox'?!!row[k]:careerText(row[k]);return out})}if(!Array.isArray(raw.files)||raw.files.length>200)throw Error('Too many attachments.');const ids=new Set();d.files=raw.files.map(f=>{if(!f||!/^[a-zA-Z0-9-]{1,80}$/.test(f.id)||ids.has(f.id)||!['image/jpeg','image/png','application/pdf'].includes(f.type)||!Number.isFinite(f.size)||f.size<0||f.size>10*1024*1024)throw Error('Invalid attachment metadata.');ids.add(f.id);return {id:f.id,name:careerText(f.name,180),type:f.type,size:f.size,section:careerText(f.section,40),record:careerText(f.record,80),side:careerText(f.side,40)}});for(const key of ['portrait','signature']){if(raw[key]&&!ids.has(raw[key]))throw Error('Missing '+key+' attachment.');d[key]=careerText(raw[key],80)}for(const key of Object.keys(careerDefaultExport))d.exportOptions[key]=typeof raw.exportOptions?.[key]==='boolean'?raw.exportOptions[key]:careerDefaultExport[key];return d}
function careerOpenDB(){if(!careerDBPromise)careerDBPromise=new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(Error('Device storage is unavailable in this browser.'));return}const r=indexedDB.open('toolbox-career-v1',1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('records'))db.createObjectStore('records',{keyPath:'owner'});if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'key'})};r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();careerDBPromise=null};resolve(r.result)};r.onerror=()=>{careerDBPromise=null;reject(Error('Could not open device storage.'))};r.onblocked=()=>{careerError='Close another older Toolbox tab, then retry storage.'}});return careerDBPromise}
async function careerRead(owner){const db=await careerOpenDB();return new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').get(owner);r.onsuccess=()=>resolve(r.result?.data||careerEmpty());r.onerror=()=>reject(Error('Could not read your career records.'))})}
async function careerWrite(owner,data,expected,files=[],snapshot=false){const db=await careerOpenDB();return new Promise((resolve,reject)=>{const tx=db.transaction(['records','files'],'readwrite'),store=tx.objectStore('records'),r=store.get(owner);let stale=false;r.onsuccess=()=>{const old=r.result?.data;if((old?.revision||0)!==expected){stale=true;tx.abort();return}if(snapshot&&old){store.put({owner:owner+':previous',data:old});for(const f of old.files||[]){const copy=tx.objectStore('files').get(owner+':'+f.id);copy.onsuccess=()=>{if(copy.result)tx.objectStore('files').put({key:owner+':previous:'+f.id,blob:copy.result.blob})}}}store.put({owner,data});for(const f of files)tx.objectStore('files').put({key:owner+':'+f.id,blob:f.blob})};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(Error('Could not save. Device storage may be full. Your previous record is kept.'));tx.onabort=()=>reject(Error(stale?'A newer career record was saved in another tab. Export your draft if needed, then reload before changing it.':'Save did not complete. Your previous record is kept.'))})}
async function careerBlob(owner,id){const db=await careerOpenDB();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(owner+':'+id);r.onsuccess=()=>resolve(r.result?.blob||null);r.onerror=()=>reject(Error('Could not read this attachment.'))})}
async function careerLoad(){const owner=careerAccount();if(!careerReady()||careerLoading||careerData&&careerOwner===owner)return;careerOwner=owner;careerLoading=true;careerError='';const epoch=++careerEpoch;try{const data=careerClean(await careerRead(owner));if(owner!==careerAccount()||epoch!==careerEpoch)return;careerData=data}catch(e){if(owner===careerAccount()&&epoch===careerEpoch)careerError=e.message}finally{if(owner===careerAccount()&&epoch===careerEpoch){careerLoading=false;if(page==='career'||page==='home')render();careerCheckExpiryAlerts();careerScheduleExpiry()}}}
async function careerSave(mutator,files=[],snapshot=false){if(!careerReady()||!careerData||careerBusy||careerOwner!==careerAccount())return false;const owner=careerOwner,epoch=careerEpoch,old=careerData;careerBusy=true;try{let d=structuredClone(old);mutator(d);d.revision=old.revision+1;d=careerClean(d);if(d.files.reduce((n,f)=>n+f.size,0)>40*1024*1024)throw Error('The device attachment limit is 40 MB. Keep a backup before replacing large files.');await careerWrite(owner,d,old.revision,files,snapshot);if(owner!==careerAccount()||epoch!==careerEpoch)return false;careerData=d;careerError='';careerCheckExpiryAlerts();return true}catch(e){if(owner===careerAccount()&&epoch===careerEpoch)careerError=e.message;return false}finally{if(owner===careerAccount()&&epoch===careerEpoch)careerBusy=false}}
function careerRelease(){for(const url of careerURLs)URL.revokeObjectURL(url);careerURLs=[]}
function careerRows(type,d=careerData){return (d?.[type]||[]).filter(r=>!r.archived)}
function careerPerson(d=careerData){return {...d.personal,fullName:d.personal.fullName||state.profile.name||'',email:d.personal.email||state.profile.email||''}}
function careerDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return '';const n=Date.parse(v+'T12:00:00Z');return Number.isFinite(n)&&new Date(n).toISOString().slice(0,10)===v?new Date(n).toLocaleDateString('en',{timeZone:'UTC',year:'numeric',month:'short',day:'2-digit'}):''}
function careerAge(dob,today=learningDate()){if(!careerDate(dob)||dob>today)return '';const a=dob.split('-').map(Number),b=today.split('-').map(Number);return String(b[0]-a[0]-(b[1]<a[1]||b[1]===a[1]&&b[2]<a[2]?1:0))}
function careerPeriod(row){if(row.period)return row.period;const end=row.current?learningDate():row.signedOff;if(!careerDate(row.joined)||!careerDate(end)||end<row.joined)return '';return Math.round((Date.parse(end)-Date.parse(row.joined))/86400000)+1+' days'+(row.current?' (to date)':'')}
function careerExpiry(row,today=learningDate()){
 if(row.validity&&row.validity!=='Has expiry date')return {kind:'neutral',label:row.validity,days:null};
 if(!careerDate(row.expires))return {kind:'neutral',label:'No expiry entered',days:null};
 const days=Math.round((Date.parse(row.expires)-Date.parse(today))/86400000);
 if(days<0)return {kind:'expired',label:'Expired',days};
 if(row.issued&&careerDate(row.issued)&&row.issued>today)return {kind:'neutral',label:'Not yet valid',days:null};
 return {kind:days<=30?'soon':'valid',label:'Valid',days};
}
function careerStatus(row){const x=careerExpiry(row);return x.days===null?x.label:x.kind==='expired'?'Expired · '+careerDate(row.expires):x.days===0?'Valid · Expires today':x.days<=30?'Valid · Expires in '+x.days+' days':'Valid to '+careerDate(row.expires)}
function careerExpiryTag(row){const x=careerExpiry(row);return `<span class="career-validity career-validity-${x.kind}">${esc(x.label)}</span><small class="career-expiry-date">${esc(x.days===null?'':x.days<0?'Expired '+careerDate(row.expires):x.days===0?'Expires today':'Expires '+careerDate(row.expires)+(x.days<=30?' · '+x.days+' days left':''))}</small>`}
function careerHeader(title,back='home'){return `<header class="learning-heading"><div><button class="text-button" data-career="${back}">← ${back==='today'?'Today':back==='home'?'Career & documents':'Back'}</button><h1>${esc(title)}</h1></div></header>`}
function careerEntryCard(){return `<section class="card career-entry"><div><span class="eyebrow">YOUR NEXT CONTRACT</span><h2>Career & documents</h2><p>Keep your sea service, organise documents, and prepare your CV.</p></div><button class="btn quiet" data-career="home">Open career tools →</button></section>`}
function careerHome(){const d=careerData,docs=[...careerRows('documents'),...careerRows('certificates')],expired=docs.filter(x=>careerExpiry(x).kind==='expired').length;app.innerHTML=careerHeader('Career & documents','today')+`<p class="career-storage">Saved on this device for ${esc(state.profile.name||'your profile')}. Career files are separate from Toolbox Cloud. Download a backup before clearing data or changing devices.</p><div class="career-actions"><button class="btn" data-career="cv">Generate CV</button><button class="btn quiet" data-career="personal">Edit career profile</button></div><div class="career-grid">${[['sea','Sea service',careerRows('sea').length+' ship records'],['documents','IDs & travel documents',careerRows('documents').length+' records'],['certificates','Certificates',careerRows('certificates').length+' records'],['plans','Plans & appointments',careerRows('plans').filter(r=>!r.done).length+' open plans'],['education','Education',careerRows('education').length+' records'],['employment','Employment',careerRows('employment').length+' records'],['vaccinations','Vaccination records',careerRows('vaccinations').length+' records'],['references','References',careerRows('references').length+' records']].map(([key,title,copy])=>`<button class="card career-tool" data-career-list="${key}"><strong>${title}</strong><small>${copy}</small><span aria-hidden="true">›</span></button>`).join('')}</div>${expired?`<p role="status">${expired} document or certificate record${expired===1?' has':'s have'} an expiry date in the past.</p>`:''}<section class="card"><span class="eyebrow">COMING SOON</span><h2>MARINA appointment integration</h2><p>Live slot checking and booking are not connected. Follow MARINA’s official eGovPH instructions for SID / SRB applications.</p><a class="text-button" href="https://marina.gov.ph/2026/05/11/breaking-marina-releases-advisory-on-exclusive-online-application-of-sid-srb-through-egovph-app/" target="_blank" rel="noopener noreferrer">Read official appointment guidance</a><p><button class="text-button" data-career-new="plans">Save a confirmed appointment</button></p></section>${careerReminderSettings()}<section class="card"><h2>Keep a separate copy</h2><p>Your backup includes private career details and attached files. Store it somewhere you control. It is not password protected.</p><button class="btn quiet" data-career="backup">Download career backup</button> <label class="career-file-btn">Restore career backup<input id="careerRestore" type="file" accept="application/json,.json"></label><p class="hint">Restoring replaces this account’s career records only. The preceding version is kept on this device.</p><button class="text-button" data-career="previous">Restore preceding version</button></section><p id="careerStatus" role="status">${esc(careerError)}</p>`;document.getElementById('careerRestore').onchange=e=>careerRestoreFile(e.target.files[0])}
function careerField([key,label,kind='text',options],value){if(kind==='checkbox')return `<label class="career-check"><input name="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;return `<label class="field ${kind==='textarea'?'career-wide':''}">${label}${kind==='textarea'?`<textarea name="${key}" rows="3" maxlength="5000">${esc(value||'')}</textarea>`:kind==='select'?`<select name="${key}"><option value="">Choose</option>${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="${key}" type="${kind}" value="${esc(value||'')}" maxlength="1000" ${['number','contact','philhealth','pagibig','sss','tin'].includes(key)?'autocomplete="off"':''}>`}</label>`}
function careerEdit(section,id=null){if(!careerData)return;careerSection=section;careerEditId=id;const existing=section==='personal'?careerPerson():careerData[section]?.find(r=>r.id===id);careerDraft=structuredClone(existing||{});careerDirty=false;careerView='edit';page='career';render()}
function careerEditView(){const personal=careerSection==='personal',schema=careerSchemas[careerSection],fields=personal?careerPersonal:schema.fields;app.innerHTML=careerHeader(personal?'Career profile':schema.singular,'cancel')+`<form id="careerForm" class="card"><p class="hint">These fields feed your CV. Enter details as shown on your own records. Empty fields stay blank.</p><div class="career-fields">${fields.map(f=>careerField(f,careerDraft[f[0]])).join('')}</div>${personal?'':`<p class="hint">${careerSection==='sea'?'Period defaults to inclusive calendar days, not a verified MARINA sea-service calculation. Enter the period from your service record to use that wording.':careerSection==='plans'?'Plans and appointments stay on the device. No booking or background notification is sent.':'For records without an expiry date, choose the correct validity option rather than inventing a date.'}</p>`}<button class="btn" ${careerBusy?'disabled':''}>Save ${personal?'career profile':'record'}</button><p id="careerStatus" role="status">${esc(careerError)}</p></form>`;const form=document.getElementById('careerForm');form.oninput=()=>{careerDirty=true};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),row={};for(const[k,,kind]of fields)row[k]=kind==='checkbox'?f.has(k):String(f.get(k)||'').trim();careerDraft=row;const problem=careerValidateRow(careerSection,row);if(problem){careerError=problem;document.getElementById('careerStatus').textContent=problem;return}const owner=careerAccount(),section=careerSection,id=careerEditId;const ok=await careerSave(d=>{if(personal)d.personal=row;else{const saved={...row,id:id||crypto.randomUUID()},index=d[section].findIndex(r=>r.id===id);if(index>=0)d[section][index]=saved;else d[section].push(saved)}});if(owner!==careerAccount())return;if(ok){careerDirty=false;careerDraft=null;if(personal)careerGo('home');else careerList(section)}else document.getElementById('careerStatus').textContent=careerError}}
function careerValidateRow(section,row){for(const[k,,kind]of section==='personal'?careerPersonal:careerSchemas[section].fields)if(kind==='date'&&row[k]&&!careerDate(row[k]))return 'Enter a valid date.';if(section==='personal'&&row.birthDate>learningDate())return 'Birthdate cannot be in the future.';if(['sea','employment'].includes(section)){if(!row.current&&row.joined&&row.signedOff&&row.signedOff<row.joined)return 'The end date cannot be before the joining date.';if(row.current&&row.signedOff)return 'Clear the sign-off/end date while this record is marked current.';if(section==='sea'&&(!row.rank||!row.vessel||!row.joined))return 'Enter the rank, vessel and joining date.'}else if(['documents','certificates','vaccinations'].includes(section)){if(!row.title)return 'Enter a document, certificate or vaccine name.';if(row.validity==='Has expiry date'&&row.issued&&row.expires&&row.expires<row.issued)return 'Expiry cannot be before issue date.'}else if(section==='education'&&!row.school)return 'Enter a school name.';else if(section==='references'&&!row.name)return 'Enter a reference name.';else if(section==='plans'&&!row.title)return 'Enter a plan title.';return ''}
function careerList(type){careerSection=type;careerView='list';careerDirty=false;page='career';render()}
function careerRowTitle(type,r){return r.vessel||r.title||r.school||r.company||r.name||careerSchemas[type].singular}
function careerListView(){const type=careerSection,s=careerSchemas[type],rows=careerRows(type).sort((a,b)=>String(b.joined||b.issued||b.due||'').localeCompare(String(a.joined||a.issued||a.due||'')));app.innerHTML=careerHeader(s.title)+`<button class="btn" data-career-new="${type}">Add ${s.singular.toLowerCase()}</button><div class="career-records">${rows.map(r=>`<article class="card"><h2>${esc(careerRowTitle(type,r))}</h2>${['documents','certificates','vaccinations'].includes(type)?careerExpiryTag(r):''}<p>${esc(type==='sea'?[r.rank,r.vesselType,careerDate(r.joined),r.current?'Currently onboard':careerDate(r.signedOff),careerPeriod(r)].filter(Boolean).join(' · '):type==='plans'?[r.done?'Completed':'Open',careerDate(r.due),r.time,r.location].filter(Boolean).join(' · '):['documents','certificates','vaccinations'].includes(type)?'':[r.course||r.position,r.years||r.location,r.contact].filter(Boolean).join(' · '))}</p><div class="career-actions"><button class="btn quiet" data-career-edit="${r.id}">Edit</button>${['documents','certificates','vaccinations'].includes(type)?`<button class="text-button" data-career-files="${r.id}">${careerExpiry(r).kind==='expired'?'Reupload / replace':'Files'} (${careerData.files.filter(f=>f.record===r.id).length})</button>`:''}<button class="text-button" data-career-archive="${r.id}">Archive</button></div></article>`).join('')||'<section class="card"><p>No records yet. Add your first record.</p></section>'}</div><details class="card"><summary>Archived records</summary>${careerData[type].filter(r=>r.archived).map(r=>`<p>${esc(careerRowTitle(type,r))} <button class="text-button" data-career-unarchive="${r.id}">Restore</button></p>`).join('')||'<p>No archived records.</p>'}</details><p id="careerStatus" role="status">${esc(careerError)}</p>`}
let careerReplaceId=null;
function careerFiles(id){careerReplaceId=null;careerEditId=id;careerView='files';page='career';render()}
function careerFilesView(){const row=careerData[careerSection].find(r=>r.id===careerEditId);if(!row){careerList(careerSection);return}const files=careerData.files.filter(f=>f.record===row.id);app.innerHTML=careerHeader(careerRowTitle(careerSection,row),'list')+`<section class="card"><h2>Document copies</h2>${careerExpiryTag(row)}<p><button class="text-button" data-career-edit="${row.id}">Update issue / expiry details</button></p><p>Reuploading a copy does not change validity. Update the dates from your renewed document.</p><input id="careerReplaceUpload" type="file" hidden accept="image/jpeg,image/png,image/webp,application/pdf"><p>Keep front and back separately. For a passport, choose the biodata page. These images are not inserted into the CV.</p><label class="field">Side / page<select id="careerSide"><option>Front</option><option>Back</option><option>Passport biodata page</option><option>Certificate / other page</option></select></label><label class="career-file-btn">Add image or PDF<input id="careerUpload" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><p class="hint">Images up to 8 MB are resized on your device. PDFs up to 10 MB. Total attachment limit: 40 MB per account on this device.</p><p id="careerStatus" role="status">${esc(careerError)}</p></section>${files.map(f=>`<section class="card"><strong>${esc(f.side)}</strong> ${careerExpiryTag(row)}<p>${esc(f.name)} · ${Math.ceil(f.size/1024)} KB</p><button class="btn quiet" data-career-replace-file="${f.id}">${careerExpiry(row).kind==='expired'?'Reupload':'Replace'} ${esc(f.side.toLowerCase())}</button> <button class="btn quiet" data-career-open-file="${f.id}">Open copy</button> <button class="text-button" data-career-download-file="${f.id}">Download</button></section>`).join('')}`;document.getElementById('careerReplaceUpload').onchange=e=>{const f=careerData.files.find(x=>x.id===careerReplaceId&&x.record===row.id&&x.section===careerSection);if(f)void careerUpload(e.target.files[0],careerSection,row.id,f.side,f.id);e.target.value=''};document.getElementById('careerUpload').onchange=e=>careerUpload(e.target.files[0],careerSection,row.id,document.getElementById('careerSide').value)}
async function careerImage(file,portrait=false,zoom=1,x=.5,y=.5){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP image.');if(file.size>8*1024*1024)throw Error('Choose an image smaller than 8 MB.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('This image could not be opened.'));i.src=url});if(img.naturalWidth*img.naturalHeight>60000000)throw Error('This image is too large. Use a smaller copy.');const canvas=document.createElement('canvas');let sx=0,sy=0,sw=img.naturalWidth,sh=img.naturalHeight;if(portrait){const ratio=35/45;sw=Math.min(sw,sh*ratio)/zoom;sh=sw/ratio;sx=(img.naturalWidth-sw)*x;sy=(img.naturalHeight-sh)*y;canvas.width=560;canvas.height=720}else{const scale=Math.min(1,1600/sw,1600/sh);canvas.width=Math.round(sw*scale);canvas.height=Math.round(sh*scale)}const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,sx,sy,sw,sh,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Could not prepare this image.')),'image/jpeg',.85))}finally{URL.revokeObjectURL(url)}}
async function careerUpload(file,section,record,side,replaceId=null){if(!file||careerBusy)return;const owner=careerAccount(),epoch=careerEpoch;const status=document.getElementById('careerStatus');if(status)status.textContent='Preparing file on this device…';try{let blob;if(file.type==='application/pdf'){if(file.size>10*1024*1024)throw Error('PDF limit is 10 MB.');const magic=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(magic!=='%PDF-')throw Error('This is not a valid PDF file.');blob=file}else blob=await careerImage(file);if(owner!==careerAccount()||epoch!==careerEpoch||page!=='career'||careerView!=='files'||careerSection!==section||careerEditId!==record)return;const id=replaceId||crypto.randomUUID(),meta={id,name:file.name.slice(0,170)+(blob.type==='image/jpeg'&&!file.name.toLowerCase().endsWith('.jpg')?'.jpg':''),type:blob.type,size:blob.size,section,record,side};const ok=await careerSave(d=>careerSetAttachment(d,meta,replaceId),[{id,blob}]);if(owner!==careerAccount())return;if(ok)render();else if(status)status.textContent=careerError}catch(e){if(owner===careerAccount()&&status)status.textContent=e.message}}
function careerSetAttachment(d,meta,replaceId){if(!d[meta.section]?.some(r=>r.id===meta.record&&!r.archived))throw Error('The document record has changed. Reopen it before uploading.');if(replaceId){const i=d.files.findIndex(f=>f.id===replaceId&&f.record===meta.record&&f.section===meta.section&&f.side===meta.side);if(i<0)throw Error('This copy has changed. Reopen the document.');d.files[i]=meta}else d.files.push(meta)}
function careerDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function careerOpenFile(id,download=false){const owner=careerAccount(),epoch=careerEpoch,f=careerData.files.find(x=>x.id===id);if(!f)return;try{const blob=await careerBlob(owner,id);if(owner!==careerAccount()||epoch!==careerEpoch)return;if(!blob)throw Error('This file is missing on the device. Restore your career backup.');if(download){careerDownload(blob,f.name);return}const url=URL.createObjectURL(blob);careerURLs.push(url);let dialog=document.getElementById('careerFileDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='careerFileDialog';dialog.className='career-file-dialog';document.body.append(dialog)}dialog.innerHTML=`<button class="btn quiet" data-career="closeFile">Close file</button><h2>${esc(f.side||f.name)}</h2>${f.type==='application/pdf'?`<object data="${url}" type="application/pdf"><p>PDF preview unavailable. Use Download to open it.</p></object>`:`<img src="${url}" alt="${esc(f.side||'Document copy')}">`}<button class="text-button" data-career-download-file="${id}">Download file</button>`;dialog.onclose=careerRelease;dialog.showModal()}catch(e){careerError=e.message;const s=document.getElementById('careerStatus');if(s)s.textContent=careerError}}
function careerCVSections(d=careerData){const p=careerPerson(d),o=d.exportOptions,valid=r=>r.validity&&r.validity!=='Has expiry date'?r.validity:careerDate(r.expires),personal=[['Family name',p.familyName,'Contact no.',p.contact],['First name',p.firstName,'PhilHealth no.',o.government?p.philhealth:''],['Middle name',p.middleName,'Pag-IBIG no.',o.government?p.pagibig:''],['Birthdate',careerDate(p.birthDate),'SSS no.',o.government?p.sss:''],['Age',careerAge(p.birthDate),'TIN',o.government?p.tin:''],['Gender',p.gender,'Email address',p.email],['Civil status',p.civilStatus,'Height',p.height],['Nationality',p.nationality,'Weight',p.weight],['Religion',p.religion,'Availability',p.availability],['Complete address',p.address,'','']];return [{title:'OBJECTIVES',text:p.objective||''},{title:'PERSONAL DETAILS',rows:personal,personal:true},{title:'EDUCATIONAL BACKGROUND',head:['Level','Name of school','S.Y.','Course'],rows:careerRows('education',d).map(r=>[r.level,r.school,r.years,r.course])},{title:'NATIONAL CERTIFICATIONS - CERTIFICATE OF PROFICIENCY (COP)',head:['Certificates','Number','Date issued','Expiry / validity'],rows:careerRows('certificates',d).map(r=>[r.title,r.number,careerDate(r.issued),valid(r)])},{title:'TRAVEL DOCUMENTS',head:['Documents','Number','Date issued','Expiry / validity'],rows:o.documents?careerRows('documents',d).map(r=>[r.title,r.number,careerDate(r.issued),valid(r)]):[]},{title:'VACCINATION',head:['Vaccine','Number','Date issued','Expiry / validity'],rows:o.vaccinations?careerRows('vaccinations',d).map(r=>[r.title,r.number,careerDate(r.issued),valid(r)]):[]},{title:'SEA BASE WORK EXPERIENCE',head:['Company','Position','Location','Date hired - Date resigned'],rows:careerRows('employment',d).map(r=>[r.company,r.position,r.location,[careerDate(r.joined),r.current?'Present':careerDate(r.signedOff)].filter(Boolean).join(' - ')])},{title:'SEA SERVICE',head:['Rank','Joined','Signed off','Period','Name of vessel','Type of vessel','GT / GRT','kW','Reason for leaving'],rows:careerRows('sea',d).sort((a,b)=>(b.joined||'').localeCompare(a.joined||'')).map(r=>[r.rank,careerDate(r.joined),r.current?'Present':careerDate(r.signedOff),careerPeriod(r),r.vessel,r.vesselType,[r.tonnage,r.tonnageUnit].filter(Boolean).join(' '),r.kw,r.reason])},{title:'CHARACTER REFERENCE',head:['Name','Position','Contact number'],rows:careerRows('references',d).map(r=>[r.name,r.position,r.contact])}]}
function careerCVTable(s){if(s.text!==undefined)return `<p class="cv-objective">${esc(s.text)||'&nbsp;'}</p>`;const count=s.head?.length||4,rows=s.rows.length?s.rows:[Array(count).fill('')];return `<table class="cv-table ${s.personal?'cv-personal':''} ${count===9?'cv-sea':''}">${s.head?`<thead><tr>${s.head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead>`:''}<tbody>${rows.map(row=>`<tr>${(s.personal&&!row[2]&&!row[3]?row.slice(0,2):row).map((v,i)=>s.personal&&i%2===0?`<th scope="row">${esc(v||'')}</th>`:`<td ${s.personal&&!row[2]&&!row[3]?'colspan="3"':''}>${esc(v||'')||'&nbsp;'}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function careerCVMarkup(d=careerData,portraitURL='',signatureURL=''){const p=careerPerson(d);return `<article id="careerCV" class="career-cv"><header class="cv-header"><div><h1>${esc(p.fullName)}</h1><p>${esc(state.profile.rank||'')}</p></div>${d.exportOptions.photo&&portraitURL?`<img class="cv-portrait" src="${portraitURL}" alt="CV portrait">`:'<div class="cv-photo-placeholder">Photo</div>'}</header>${careerCVSections(d).map(s=>`<section class="cv-section"><h2>${s.title}</h2>${careerCVTable(s)}</section>`).join('')}${d.exportOptions.declaration?'<p class="cv-declaration">I hereby certify that the information given above is true and correct to the best of my knowledge and belief and that I have not withheld any information that would affect my application unfavorably.</p>':''}<footer class="cv-signature">${d.exportOptions.signature&&signatureURL?`<img src="${signatureURL}" alt="Signature">`:'<div class="cv-signature-space"></div>'}<strong>${esc(p.fullName)}</strong><span>Signature over Printed Name</span></footer></article>`}
function careerCVView(){const p=careerPerson();app.innerHTML=careerHeader('Generate your CV')+`<section class="card career-cv-controls"><h2>Review before exporting</h2><p>Uses the section order and table fields from the supplied CV sample. Every saved entry in each included section is printed; long sections continue onto additional pages.</p>${!p.fullName?'<p role="status">Add your full name in Career profile.</p>':''}<p class="hint">Check names, dates, numbers and current employment. Toolbox does not verify these records.</p><div class="career-actions"><button class="btn quiet" data-career="personal">Edit career profile</button><button class="btn quiet" data-career="portrait">CV portrait</button><button class="btn quiet" data-career="signature">Signature image</button></div><fieldset><legend>Choose private information to include</legend>${[['government','Government ID numbers (SSS, PhilHealth, Pag-IBIG, TIN)'],['documents','Travel documents and other ID records with numbers'],['vaccinations','Vaccination records'],['photo','CV portrait'],['signature','Signature image'],['declaration','Declaration']].map(([key,label])=>`<label class="career-check"><input data-career-option="${key}" type="checkbox" ${careerData.exportOptions[key]?'checked':''}>${label}</label>`).join('')}</fieldset><p class="hint">Unchecked sections keep the sample’s headings and blank rows. Document scans, plans, journals and practice scores are excluded.</p><div class="career-actions"><button class="btn" data-career="pdf">Download PDF</button><button class="btn quiet" data-career="print">Print / Save as PDF</button><button class="btn quiet" data-career="html">Download CV file (.html)</button></div><p class="hint">Print opens your device’s print dialog. Choose Save as PDF where available. Use A4 portrait, scale 100%, and turn browser headers/footers off.</p><p id="careerStatus" role="status">${esc(careerError)}</p></section><style>${careerPrintCSS}</style><div class="career-cv-scroll" aria-label="CV print preview">${careerCVMarkup()}</div>`;void careerLoadCVImages()}
async function careerLoadCVImages(){const owner=careerAccount(),epoch=careerEpoch;for(const key of ['portrait','signature']){const id=careerData[key];if(!id)continue;try{const blob=await careerBlob(owner,id);if(owner!==careerAccount()||epoch!==careerEpoch||page!=='career'||careerView!=='cv')return;if(blob){const url=URL.createObjectURL(blob);careerURLs.push(url);const old=document.getElementById('careerCV');if(old){let image=old.querySelector(key==='portrait'?'.cv-portrait':'.cv-signature img');if(!image){image=document.createElement('img');image.className=key==='portrait'?'cv-portrait':'';image.alt=key==='portrait'?'CV portrait':'Signature';if(key==='portrait'){old.querySelector('.cv-photo-placeholder')?.replaceWith(image)}else old.querySelector('.cv-signature-space')?.replaceWith(image)}image.src=url;if(key==='portrait')image.hidden=!careerData.exportOptions.photo;else image.hidden=!careerData.exportOptions.signature}}}catch(e){careerError=e.message}}}
let careerPhotoFile=null;
function careerPhotoView(){const portrait=careerView==='portrait';app.innerHTML=careerHeader(portrait?'CV portrait':'Signature image','cv')+`<section class="card"><p>${portrait?'Choose a portrait, then adjust the crop. The saved image has a 35 × 45 mm aspect ratio for the CV. It is not a government passport-photo validation.':'Choose a cropped image of your own signature. It stays off the CV until you select Include signature.'}</p><label class="career-file-btn">Choose image<input id="careerPhotoInput" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="careerPhotoPreview" class="${portrait?'career-crop':'career-sign-preview'}"></div>${portrait?'<label class="field">Zoom<input id="careerZoom" type="range" min="1" max="3" step=".05" value="1"></label><label class="field">Horizontal position<input id="careerPhotoX" type="range" min="0" max="1" step=".01" value=".5"></label><label class="field">Vertical position<input id="careerPhotoY" type="range" min="0" max="1" step=".01" value=".5"></label>':''}<button class="btn" id="careerSavePhoto" disabled>Save ${portrait?'portrait':'signature'}</button><p id="careerStatus" role="status"></p></section>`;careerPhotoFile=null;const input=document.getElementById('careerPhotoInput');input.onchange=()=>{careerPhotoFile=input.files[0];void careerPreviewCrop()};for(const id of ['careerZoom','careerPhotoX','careerPhotoY']){const el=document.getElementById(id);if(el)el.oninput=()=>{void careerPreviewCrop()}}document.getElementById('careerSavePhoto').onclick=careerSavePhoto}
let careerCropEpoch=0,careerPreviewBlob=null;
async function careerPreviewCrop(){const file=careerPhotoFile;if(!file)return;const owner=careerAccount(),epoch=++careerCropEpoch,view=careerView;document.getElementById('careerSavePhoto').disabled=true;try{const blob=await careerImage(file,view==='portrait',Number(document.getElementById('careerZoom')?.value||1),Number(document.getElementById('careerPhotoX')?.value||.5),Number(document.getElementById('careerPhotoY')?.value||.5));if(epoch!==careerCropEpoch||owner!==careerAccount()||careerView!==view)return;careerPreviewBlob=blob;careerRelease();const url=URL.createObjectURL(blob);careerURLs.push(url);document.getElementById('careerPhotoPreview').innerHTML=`<img src="${url}" alt="Prepared ${view==='portrait'?'portrait':'signature'}">`;document.getElementById('careerSavePhoto').disabled=false}catch(e){if(epoch===careerCropEpoch&&owner===careerAccount())document.getElementById('careerStatus').textContent=e.message}}
async function careerSavePhoto(){if(!careerPreviewBlob||careerBusy)return;const key=careerView==='portrait'?'portrait':'signature',owner=careerAccount(),id=crypto.randomUUID(),blob=careerPreviewBlob;const ok=await careerSave(d=>{const old=d[key];d.files=d.files.filter(f=>f.id!==old);d[key]=id;d.files.push({id,name:key+'.jpg',type:'image/jpeg',size:blob.size,section:key,record:key,side:key})},[{id,blob}]);if(owner!==careerAccount())return;if(ok)careerGo('cv');else document.getElementById('careerStatus').textContent=careerError}
async function careerPortableCV(){const d=structuredClone(careerData),owner=careerAccount(),epoch=careerEpoch,images={};for(const key of ['portrait','signature'])if(d[key]&&d.exportOptions[key==='portrait'?'photo':'signature']){const b=await careerBlob(owner,d[key]);if(!b)throw Error('A selected CV image is missing. Restore your backup or deselect it.');images[key]=await careerDataURL(b)}if(owner!==careerAccount()||epoch!==careerEpoch)throw Error('Account changed. Open the CV again.');return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seafarer CV</title><style>'+careerPrintCSS+'</style></head><body>'+careerCVMarkup(d,images.portrait||'',images.signature||'')+'</body></html>'}
async function careerPrint(){if(careerView!=='cv')return;try{await careerPortableCV();if(careerView!=='cv')return;document.body.classList.add('career-printing');window.print()}catch(e){careerError=e.message;document.getElementById('careerStatus').textContent=e.message}}
function careerDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read this file.'));r.readAsDataURL(blob)})}
async function careerBackup(){if(!careerData||careerBusy)return;const owner=careerAccount(),epoch=careerEpoch,data=structuredClone(careerData),files=[];try{for(const f of data.files){const blob=await careerBlob(owner,f.id);if(!blob)throw Error('An attachment is missing; restore it before making a complete backup.');files.push({id:f.id,data:await careerDataURL(blob)})}if(owner!==careerAccount()||epoch!==careerEpoch)return;careerDownload(new Blob([JSON.stringify({app:'Toolbox career',version:1,owner,exportedAt:new Date().toISOString(),data,files})],{type:'application/json'}),'Toolbox-career-backup-'+learningDate()+'.json')}catch(e){careerError=e.message;document.getElementById('careerStatus').textContent=e.message}}
function careerDecodeBackup(raw,owner){if(raw?.app!=='Toolbox career'||raw.version!==1||raw.owner!==owner)throw Error('Choose a Toolbox career backup made for this same account.');const d=careerClean(raw.data);if(!Array.isArray(raw.files)||raw.files.length!==d.files.length)throw Error('Backup files are incomplete.');const blobs=[],seen=new Set();for(const f of raw.files){const meta=d.files.find(m=>m.id===f.id);if(!meta||seen.has(f.id)||typeof f.data!=='string'||!f.data.startsWith('data:'+meta.type+';base64,'))throw Error('Invalid backup attachment.');seen.add(f.id);const encoded=f.data.split(',')[1];if(encoded.length>14*1024*1024)throw Error('Attachment is too large.');const binary=atob(encoded),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));if(bytes.length!==meta.size)throw Error('Backup file size mismatch.');blobs.push({id:f.id,blob:new Blob([bytes],{type:meta.type})})}return {data:d,blobs}}
async function careerRestoreFile(file){if(!file||careerBusy)return;const owner=careerAccount(),epoch=careerEpoch;try{if(file.size>58*1024*1024)throw Error('Backup limit is 58 MB.');const parsed=careerDecodeBackup(JSON.parse(await file.text()),owner);if(owner!==careerAccount()||epoch!==careerEpoch)return;if(!window.confirm('Replace this account’s career records with this backup? Your preceding career version is kept. Journals and learning progress are unaffected.'))return;const ok=await careerSave(d=>Object.assign(d,parsed.data,{revision:d.revision}),parsed.blobs,true);if(owner===careerAccount()){if(ok)careerGo('home');else document.getElementById('careerStatus').textContent=careerError}}catch(e){if(owner===careerAccount())document.getElementById('careerStatus').textContent=e.message}}
async function careerPrevious(){const owner=careerAccount(),epoch=careerEpoch;try{const data=await careerRead(owner+':previous');if(owner!==careerAccount()||epoch!==careerEpoch)return;if(!data.revision)throw Error('No preceding restored version is stored.');if(!window.confirm('Restore the preceding career version? Your current version will become the preceding version.'))return;const files=[];for(const f of data.files){const blob=await careerBlob(owner+':previous',f.id);if(!blob)throw Error('A preceding attachment is missing. Restore an exported backup instead.');files.push({id:f.id,blob})}if(owner!==careerAccount()||epoch!==careerEpoch)return;const ok=await careerSave(d=>Object.assign(d,careerClean(data),{revision:d.revision}),files,true);if(owner===careerAccount()){if(ok)render();else document.getElementById('careerStatus').textContent=careerError}}catch(e){if(owner===careerAccount())document.getElementById('careerStatus').textContent=e.message}}
function careerCanLeave(){return !careerBusy&&(!careerDirty||window.confirm('Leave without saving these career form changes?'))}
function careerGo(view='home'){if(!careerCanLeave())return;careerRelease();careerCropEpoch++;careerPreviewBlob=null;careerPhotoFile=null;careerDirty=false;careerView=view;page='career';render();window.scrollTo(0,0)}
function careerRender(){if(!careerData){app.innerHTML=careerHeader('Career & documents','today')+`<section class="card"><p role="status">${esc(careerError||'Opening your device records…')}</p>${careerError?'<button class="btn quiet" data-career="retry">Retry storage</button>':''}</section>`;if(!careerLoading&&!careerError)void careerLoad();return}if(careerView==='edit')careerEditView();else if(careerView==='list')careerListView();else if(careerView==='files')careerFilesView();else if(careerView==='cv')careerCVView();else if(['portrait','signature'].includes(careerView))careerPhotoView();else careerHome()}
const careerOldToday=learningToday;learningToday=function(){careerOldToday();app.insertAdjacentHTML('beforeend',careerEntryCard()+careerExpirySummary());if(!careerData&&!careerLoading&&!careerError&&careerReady())setTimeout(()=>{if(!careerData&&!careerLoading&&!careerError&&careerReady())void careerLoad()},0)};
const careerOldProfileSummary=profileSummary;profileSummary=function(){careerOldProfileSummary();const card=app.querySelector('.profile-summary')||app.querySelector('.card');if(card&&!app.querySelector('[data-career="cv"]'))card.insertAdjacentHTML('beforeend','<div class="career-actions career-profile-buttons"><button class="btn" data-career="cv">Generate CV</button><button class="btn quiet" data-career="home">Career & documents</button></div>')};
// One current welcome, with no old community tour. Returning sessions keep their route.
welcomeView=function(){app.innerHTML='<section class="career-welcome"><span class="eyebrow">BULLETPROOF SEAFARER</span><img src="assets/toolbox-spanner.png" width="220" height="280" alt="Your Toolbox companion welcoming you aboard"><h1>Toolbox</h1><p>Your learning. Your experience.<br>Ready for your next step at sea.</p><button class="btn" data-career="enter">Open Toolbox</button><small>Study, journal, and prepare for your next contract.</small></section>'};
gettingStartedView=function(){welcomeView()};
cloudReturnCard=function(){};
const careerOldNav=nav;nav=function(p){if(page==='career'&&p!=='career'&&!careerCanLeave())return;if(p==='career'){careerGo();return}if(state.hubOnboardingCompleted&&['welcome','gettingstarted','ask','detail','explore','activity'].includes(p))p='home';careerRelease();careerOldNav(p)};
const careerOldRender=render;render=function(){const owner=careerAccount();if(owner!==careerOwner){careerEpoch++;careerCropEpoch++;careerOwner=owner;careerData=null;careerLoading=false;careerBusy=false;careerDirty=false;careerDraft=null;careerPhotoFile=null;careerPreviewBlob=null;careerView='home';careerError='';careerRelease();document.getElementById('careerFileDialog')?.close?.()}if(state.hubOnboardingCompleted&&careerReady()&&['welcome','gettingstarted','ask','detail','explore','activity'].includes(page))page='home';document.body.classList.remove('career-printing');if(page==='career'&&careerReady()){document.body.classList.remove('intro-mode','toolbox-writing');applyTheme();renderNav();document.querySelector('#sectionName').textContent='Career & documents';uiHeader();careerRender();hubRecordRoute();hubRefreshNavigation();hubCompactScreen();hubApplyBrand();cloudSyncNotice();return}if(page!=='career')careerRelease();careerOldRender()};
const careerOldSnapshot=hubRouteSnapshot,careerOldRouteKey=hubRouteKey,careerOldBack=hubBack;
hubRouteSnapshot=function(){return {...careerOldSnapshot(),career:page==='career'?{view:careerView,section:careerSection,id:careerEditId}:null}};
hubRouteKey=function(r){return careerOldRouteKey(r)+(r.career?JSON.stringify(r.career):'')};
hubBack=function(){if(page==='career'&&!careerCanLeave())return true;careerDirty=false;careerRelease();const r=hubRouteHistory.at(-2)?.career;if(r){careerView=r.view==='edit'?'list':r.view;careerSection=r.section;careerEditId=r.id}return careerOldBack()};
hubDestinations.push(['career','Career & documents','Sea service certificates IDs travel documents CV resume plans appointments']);
hubQuickGuides.career=['Career & documents',['Add your ship experience, documents and career profile. These records stay on this device, separately from Toolbox Cloud.','Generate CV gathers your saved entries. Choose private fields, inspect the preview, then Print / Save as PDF.','Keep a career backup before changing devices or clearing browser data. Restoring affects only career records for the same account.']];
const careerOldPrivacy=privacyView;privacyView=function(){careerOldPrivacy();app.insertAdjacentHTML('beforeend','<section class="card"><h2>Career records and document copies</h2><p>Career profile, sea service, document numbers, uploaded files, vaccination records, plans and CV images are stored separately in this browser’s account-scoped IndexedDB. They are not added to public profiles or automatically synced to Supabase. Device storage and downloaded backups are not an encrypted document vault. Other people with access to this browser profile may be able to access them. Clearing site data can remove them. Export a backup for device changes. PDF/HTML exports include only the sections you select; you control any later sharing.</p></section>')};
window.addEventListener('afterprint',()=>document.body.classList.remove('career-printing'));
window.addEventListener('beforeunload',e=>{if(careerDirty||careerBusy){e.preventDefault();e.returnValue=''}});
document.addEventListener('change',async e=>{const key=e.target.dataset?.careerOption;if(!key||!Object.hasOwn(careerDefaultExport,key)||!careerReady())return;const owner=careerAccount(),value=e.target.checked,ok=await careerSave(d=>{d.exportOptions[key]=value});if(owner===careerAccount()){if(ok)render();else{e.target.checked=!value;document.getElementById('careerStatus').textContent=careerError}}});
document.addEventListener('click',async e=>{const b=e.target.closest?.('button');if(!b||b.disabled||!Object.keys(b.dataset).some(k=>k.startsWith('career')))return;e.preventDefault();e.stopImmediatePropagation();const d=b.dataset;if(d.career==='enter'){if(state.hubOnboardingCompleted){nav('home');return}state.hubTourCompleted=true;if(!persist())return;page='setup';render();return}if(!careerReady())return;if(d.careerReplaceFile){careerReplaceId=d.careerReplaceFile;document.getElementById('careerReplaceUpload')?.click();return}if(d.careerOpenFile){void careerOpenFile(d.careerOpenFile);return}if(d.careerDownloadFile){void careerOpenFile(d.careerDownloadFile,true);return}if(d.careerList){if(careerCanLeave())careerList(d.careerList);return}if(d.careerNew){careerEdit(d.careerNew);return}if(d.careerEdit){careerEdit(careerSection,d.careerEdit);return}if(d.careerFiles){careerFiles(d.careerFiles);return}if(d.careerArchive||d.careerUnarchive){const id=d.careerArchive||d.careerUnarchive,owner=careerAccount(),type=careerSection;await careerSave(data=>{const row=data[type].find(r=>r.id===id);if(row)row.archived=!!d.careerArchive});if(owner===careerAccount())render();return}switch(d.career){case'enableExpiryAlerts':void careerEnableExpiryAlerts();break;case'disableExpiryAlerts':careerSaveReminderPrefs({...careerReminderPrefs(),enabled:false});render();break;case'expiryCalendar':careerDownload(new Blob([careerExpiryCalendar()],{type:'text/calendar;charset=utf-8'}),'Toolbox-Document-Reminders.ics');break;case'today':nav('home');break;case'personal':careerEdit('personal');break;case'list':careerList(careerSection);break;case'cancel':if(careerCanLeave()){careerDirty=false;careerDraft=null;if(careerSection==='personal')careerGo();else careerList(careerSection)}break;case'retry':careerDBPromise=null;careerError='';void careerLoad();break;case'pdf':void careerDownloadPDF();break;case'print':void careerPrint();break;case'html':try{careerDownload(new Blob([await careerPortableCV()],{type:'text/html;charset=utf-8'}),'Toolbox-CV.html')}catch(err){document.getElementById('careerStatus').textContent=err.message}break;case'backup':void careerBackup();break;case'previous':void careerPrevious();break;case'closeFile':document.getElementById('careerFileDialog')?.close();break;default:careerGo(d.career||'home')}} ,true);

function careerReminderKey(){return 'toolbox-document-reminders-v1:'+careerAccount()}
function careerReminderPrefs(){try{return JSON.parse(localStorage.getItem(careerReminderKey()))||{enabled:false,sent:{}}}catch{return {enabled:false,sent:{}}}}
function careerSaveReminderPrefs(p){try{localStorage.setItem(careerReminderKey(),JSON.stringify(p));return true}catch{careerError='Could not save reminder settings on this device.';return false}}
function careerExpiryItems(today=learningDate()){return ['documents','certificates','vaccinations'].flatMap(section=>careerRows(section).map(row=>({section,row,...careerExpiry(row,today)}))).filter(x=>x.days!==null&&x.days<=30)}
function careerExpirySummary(){if(!careerData||careerOwner!==careerAccount())return '';const items=careerExpiryItems(),expired=items.filter(x=>x.days<0).length;if(!items.length)return '';return `<section class="card career-expiry-summary"><h2>Document reminders</h2><p>${expired} expired · ${items.length-expired} expiring within 30 days</p><button class="text-button" data-career="home">Review documents →</button></section>`}
function careerReminderSettings(){const p=careerReminderPrefs();return `<section class="card"><h2>Important expiry reminders</h2><p>One grouped browser alert per day at most, at 30 days, 7 days, the expiry day, and after expiry. No document numbers or photos appear in alerts.</p><button class="btn quiet" data-career="${p.enabled?'disableExpiryAlerts':'enableExpiryAlerts'}">${p.enabled?'Turn off expiry alerts':'Enable expiry alerts'}</button><p class="hint">Alerts are checked while Toolbox is open. Background web push is not connected. For reminders while the app is closed, import the calendar file into your phone calendar and enable its alerts. Re-export after renewals and replace old calendar events.</p><button class="text-button" data-career="expiryCalendar">Download expiry calendar (.ics)</button></section>`}
async function careerEnableExpiryAlerts(){const owner=careerAccount();try{if(typeof Notification==='undefined')throw Error('Browser alerts are unavailable. Use the expiry calendar.');const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(owner!==careerAccount()||!careerReady())return;if(permission!=='granted')throw Error('Notification permission was not granted. In-app reminders remain available.');if(!careerSaveReminderPrefs({...careerReminderPrefs(),enabled:true}))throw Error(careerError);careerCheckExpiryAlerts();render()}catch(e){if(owner===careerAccount()){careerError=e.message;const n=document.getElementById('careerStatus');if(n)n.textContent=e.message}}}
let careerAlertBusy=false,careerExpiryClock=null;
function careerReminderStage(x){return x.days<0?'expired':x.days===0?'today':x.days<=7?'7':'30'}
async function careerCheckExpiryAlerts(){if(navigator.locks?.request)return navigator.locks.request('toolbox-expiry-alerts:'+careerAccount(),{ifAvailable:true},lock=>lock?careerRunExpiryAlerts():undefined);return careerRunExpiryAlerts()}
async function careerRunExpiryAlerts(){if(careerAlertBusy||document.hidden||!careerReady()||!careerData||careerOwner!==careerAccount()||typeof Notification==='undefined'||Notification.permission!=='granted')return;const p=careerReminderPrefs(),today=learningDate(),owner=careerAccount(),epoch=careerEpoch;if(!p.enabled||p.last===today)return;const pending=careerExpiryItems().filter(x=>!p.sent?.[x.section+':'+x.row.id+':'+x.row.expires+':'+careerReminderStage(x)]);if(!pending.length)return;careerAlertBusy=true;try{const reg=await navigator.serviceWorker?.getRegistration?.();if(owner!==careerAccount()||epoch!==careerEpoch||document.hidden||!careerReminderPrefs().enabled)return;const options={body:pending.length+' document records need an expiry review. Open Career & documents.',tag:'toolbox-document-expiry',data:{toolboxExpiry:true}};if(reg?.active&&reg.showNotification)await reg.showNotification('Toolbox · Document reminder',options);else {const n=new Notification('Toolbox · Document reminder',options);n.onclick=()=>{window.focus?.();if(owner===careerAccount())careerGo();n.close?.()}}if(owner===careerAccount()&&epoch===careerEpoch&&careerReminderPrefs().enabled){p.last=today;p.sent={};for(const x of careerExpiryItems())if(x.days!==null){const key=x.section+':'+x.row.id+':'+x.row.expires+':';for(const stage of ['30','7','today','expired'])if(careerReminderPrefs().sent?.[key+stage])p.sent[key+stage]=today}for(const x of pending)p.sent[x.section+':'+x.row.id+':'+x.row.expires+':'+careerReminderStage(x)]=today;careerSaveReminderPrefs(p)}}catch{/* Keep in-app reminders; retry only on the next open/focus/save. */}finally{careerAlertBusy=false}}
function careerScheduleExpiry(){if(careerExpiryClock!==null)clearTimeout(careerExpiryClock);careerExpiryClock=null;if(document.hidden||!careerReady()||!careerData)return;const now=new Date(),next=new Date(now);next.setHours(24,0,1,0);careerExpiryClock=setTimeout(()=>{careerExpiryClock=null;if(!document.hidden&&careerReady()){careerCheckExpiryAlerts();if(!careerDirty&&!careerBusy&&['home','career'].includes(page))render();careerScheduleExpiry()}},next-now)}
function careerExpiryCalendar(today=learningDate()){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Toolbox//Document reminders//EN','CALSCALE:GREGORIAN'];for(const section of ['documents','certificates','vaccinations'])for(const r of careerRows(section)){if(careerExpiry(r,today).days===null)continue;for(const offset of [30,7,0,-1]){const date=new Date(Date.parse(r.expires+'T12:00:00Z')-offset*86400000).toISOString().slice(0,10);if(date<today)continue;lines.push('BEGIN:VEVENT','UID:toolbox-doc-'+r.id+'-'+r.expires+'-'+offset+'@toolbox','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'),'DTSTART:'+date.replaceAll('-','')+'T090000','SUMMARY:Toolbox - Review document expiry','DESCRIPTION:Open Career and documents to review your records. Replace this event after renewal.','BEGIN:VALARM','TRIGGER:PT0S','ACTION:DISPLAY','DESCRIPTION:Review Toolbox document expiry','END:VALARM','END:VEVENT')}}lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n'}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){careerCheckExpiryAlerts();if(careerReady()&&careerData&&!careerDirty&&!careerBusy&&['home','career'].includes(page))render()}careerScheduleExpiry()});
window.addEventListener('focus',()=>{careerCheckExpiryAlerts();careerScheduleExpiry()});
navigator.serviceWorker?.addEventListener?.('message',e=>{if(e.data?.type==='OPEN_CAREER_EXPIRY'&&careerReady())careerGo()});
if(typeof location!=='undefined'&&location.hash==='#document-reminders'&&careerReady())careerView='home',page='career';
render();
